"""
title: Jira Agent for Open-WebUI (OAuth 3LO, Per-User)
description: Enterprise Jira tool using Atlassian OAuth (3LO). Every action runs as the real OpenWebUI user (no shared username/password/PAT). Supports search, view, create, comment, assign, transition. Optional OpenAI-assisted project-name matching.
repository: https://github.com/taylorwilsdon/open-webui-tools
author: @taylorwilsdon (adapted by ChatGPT)
version: 2.0.0
changelog:
  - 2.0.0: Replace username/password/PAT with Atlassian OAuth 3LO per-user tokens + cloudId base URL (api.atlassian.com). Add connect/complete/disconnect tools. Keep JQL helpers; fix assignee to accountId; enforce /rest/api/3/search/jql.
  - 1.0.3: Previous PAT/basic auth version (deprecated for enterprise use)
"""

import json
import os
import re
import time
import uuid
import difflib
import threading
from typing import Any, Awaitable, Callable, Dict, Optional, List, Tuple

import requests
from pydantic import BaseModel, Field
from pydantic import field_validator, model_validator

# -----------------------------
# Optional OpenAI (project matching only)
# -----------------------------

_OPENAI_AVAILABLE = False
_OPENAI_CLIENT = None
try:
    # New SDK style
    from openai import OpenAI  # type: ignore

    _OPENAI_AVAILABLE = True
except Exception:
    try:
        import openai  # type: ignore

        _OPENAI_AVAILABLE = True
    except Exception:
        _OPENAI_AVAILABLE = False


# -----------------------------
# Minimal in-memory token store (DEMO)
# Replace with encrypted DB/KMS in production.
# -----------------------------
_TOKEN_LOCK = threading.Lock()
BASE_TOKEN_DIR = "/data/openwebui/jira_oauth"
os.makedirs(BASE_TOKEN_DIR, exist_ok=True)


# -----------------------------
# Event Emitter
# -----------------------------
class EventEmitter:
    def __init__(self, event_emitter: Callable[[dict], Awaitable[None]]):
        self.event_emitter = event_emitter

    async def emit_status(
        self, description: str, done: bool, error: bool = False
    ) -> None:
        if error and not done:
            raise ValueError("Error status must also be marked as done")
        icon = "✅" if done and not error else "🚫" if error else "💬"
        await self.event_emitter(
            {
                "data": {
                    "description": f"{icon} {description}",
                    "status": "complete" if done else "in_progress",
                    "done": done,
                },
                "type": "status",
            }
        )

    async def emit_message(self, content: str) -> None:
        if not content:
            raise ValueError("Message content cannot be empty")
        await self.event_emitter({"data": {"content": content}, "type": "message"})

    async def emit_table(
        self,
        headers: List[str],
        rows: List[List[Any]],
        title: Optional[str] = "Results",
    ) -> None:
        if not headers:
            raise ValueError("Table must have at least one header")
        if any(len(r) != len(headers) for r in rows):
            raise ValueError("All rows must have the same number of columns as headers")

        table = (
            f"### {title}\n\n|"
            + "|".join(headers)
            + "|\n|"
            + "|".join(["---"] * len(headers))
            + "|\n"
        )
        for row in rows:
            safe = [str(c).replace("|", "\\|") for c in row]
            table += "|" + "|".join(safe) + "|\n"
        table += "\n"
        await self.emit_message(table)


# -----------------------------
# Exceptions
# -----------------------------
class JiraApiError(Exception):
    pass


# -----------------------------
# Atlassian OAuth 3LO Client
# -----------------------------
class AtlassianOAuth:
    AUTH_URL = "https://auth.atlassian.com/authorize"
    TOKEN_URL = "https://auth.atlassian.com/oauth/token"
    ACCESSIBLE_RESOURCES_URL = (
        "https://api.atlassian.com/oauth/token/accessible-resources"
    )

    def __init__(
        self,
        client_id: str,
        client_secret: str,
        redirect_uri: str,
        scopes: str,
        audience: str = "api.atlassian.com",
    ):
        self.client_id = (client_id or "").strip()
        self.client_secret = (client_secret or "").strip()
        self.redirect_uri = (redirect_uri or "").strip()
        self.scopes = (scopes or "").strip()
        self.audience = (audience or "api.atlassian.com").strip()

        if not self.client_id or not self.client_secret or not self.redirect_uri:
            raise JiraApiError(
                "OAuth config missing. Please set ATLASSIAN_CLIENT_ID / ATLASSIAN_CLIENT_SECRET / ATLASSIAN_REDIRECT_URI as env vars."
            )

    def build_authorize_url(self, state: str) -> str:
        # response_type=code is standard auth code flow
        params = {
            "audience": self.audience,
            "client_id": self.client_id,
            "scope": self.scopes,
            "redirect_uri": self.redirect_uri,
            "state": state,
            "response_type": "code",
            "prompt": "consent",
        }
        return self.AUTH_URL + "?" + requests.compat.urlencode(params)

    def exchange_code_for_token(self, code: str) -> Dict[str, Any]:
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "client_secret": self.client_secret,
            "code": code,
            "redirect_uri": self.redirect_uri,
        }
        r = requests.post(
            self.TOKEN_URL, json=payload, headers={"Accept": "application/json"}
        )
        if r.status_code < 200 or r.status_code >= 300:
            raise JiraApiError(
                f"OAuth token exchange failed ({r.status_code}): {r.text}"
            )
        return r.json()

    def refresh_access_token(self, refresh_token: str) -> Dict[str, Any]:
        payload = {
            "grant_type": "refresh_token",
            "client_id": self.client_id,
            "client_secret": self.client_secret,
            "refresh_token": refresh_token,
        }
        r = requests.post(
            self.TOKEN_URL, json=payload, headers={"Accept": "application/json"}
        )
        if r.status_code < 200 or r.status_code >= 300:
            raise JiraApiError(f"OAuth refresh failed ({r.status_code}): {r.text}")
        return r.json()

    def get_accessible_resources(self, access_token: str) -> List[Dict[str, Any]]:
        r = requests.get(
            self.ACCESSIBLE_RESOURCES_URL,
            headers={
                "Authorization": f"Bearer {access_token}",
                "Accept": "application/json",
            },
        )
        if r.status_code < 200 or r.status_code >= 300:
            raise JiraApiError(
                f"Failed to fetch accessible resources ({r.status_code}): {r.text}"
            )
        data = r.json()
        if not isinstance(data, list):
            raise JiraApiError(f"Unexpected accessible-resources response: {data}")
        return data


# -----------------------------
# Jira Client (OAuth + cloudId)
# Base URL MUST be: https://api.atlassian.com/ex/jira/{cloudId}
# -----------------------------
class Jira:
    def __init__(
        self,
        access_token: str,
        cloud_id: str,
        cloud_url: str = "",
        openai_api_key: str = "",
    ):
        if not access_token or not cloud_id:
            raise JiraApiError("Missing access_token or cloud_id for Jira client")

        self.access_token = access_token
        self.cloud_id = cloud_id
        self.cloud_url = (cloud_url or "").rstrip("/")  # optional (for /browse links)
        self.base_url = f"https://api.atlassian.com/ex/jira/{cloud_id}".rstrip("/")

        self.headers = {
            "Authorization": f"Bearer {access_token}",
            "Accept": "application/json",
            "Content-Type": "application/json",
        }

        self._use_openai = bool(openai_api_key and _OPENAI_AVAILABLE)
        self._openai_key = openai_api_key or ""

        # init client if possible
        global _OPENAI_CLIENT
        if self._use_openai and _OPENAI_CLIENT is None:
            try:
                if "OpenAI" in globals():
                    _OPENAI_CLIENT = OpenAI(api_key=self._openai_key)  # type: ignore
                else:
                    import openai as _legacy_openai  # type: ignore

                    _legacy_openai.api_key = self._openai_key
                    _OPENAI_CLIENT = _legacy_openai
            except Exception:
                self._use_openai = False

    # ---------- helpers ----------
    def _handle_response(self, response: requests.Response, operation: str) -> Any:
        if 200 <= response.status_code < 300:
            if response.content:
                return response.json()
            return {}
        # Surface Atlassian errors clearly
        if response.status_code == 401:
            raise JiraApiError(
                "Authentication failed (401). User token is invalid/expired."
            )
        if response.status_code == 403:
            raise JiraApiError(
                "Permission denied (403). The user does not have access (Browse Projects / Issue security / role/permissions)."
            )
        if response.status_code == 410:
            raise JiraApiError(
                "Endpoint removed (410). Use /rest/api/3/search/jql for search."
            )
        raise JiraApiError(
            f"Jira API error ({response.status_code}) during {operation}: {response.text}"
        )

    def _browse_link(self, issue_key: str) -> str:
        # Prefer site URL for browse links (nice UX)
        if self.cloud_url:
            return f"{self.cloud_url}/browse/{issue_key}"
        # fallback: no pretty browse URL
        return issue_key

    # ---------- HTTP ----------
    def get(self, endpoint: str, params: Dict[str, Any] = None) -> Any:
        url = f"{self.base_url}/rest/api/3/{endpoint}"
        r = requests.get(url, params=params, headers=self.headers)
        return self._handle_response(r, f"GET {endpoint}")

    def post(self, endpoint: str, data: Dict[str, Any]) -> Any:
        url = f"{self.base_url}/rest/api/3/{endpoint}"
        r = requests.post(url, json=data, headers=self.headers)
        return self._handle_response(r, f"POST {endpoint}")

    def put(self, endpoint: str, data: Dict[str, Any]) -> Any:
        url = f"{self.base_url}/rest/api/3/{endpoint}"
        r = requests.put(url, json=data, headers=self.headers)
        return self._handle_response(r, f"PUT {endpoint}")

    # ---------- Directory ----------
    def search_users(self, query: str, max_results: int = 25) -> List[Dict[str, str]]:
        # Jira Cloud: /user/search supports "query"
        data = self.get(
            "user/search", params={"query": query, "maxResults": max_results}
        )
        if not isinstance(data, list):
            return []
        exact = [
            u for u in data if (u.get("displayName", "") or "").lower() == query.lower()
        ]
        candidates = exact if exact else data
        out = []
        for u in candidates:
            out.append(
                {
                    "accountId": u.get("accountId", ""),
                    "displayName": u.get("displayName", ""),
                }
            )
        return out

    def search_projects(
        self, query: str = "", max_results: int = 1000
    ) -> List[Dict[str, str]]:
        data = self.get(
            "project/search", params={"query": query, "maxResults": max_results}
        )
        values = data.get("values", []) if isinstance(data, dict) else []
        out = []
        for p in values:
            out.append(
                {
                    "key": p.get("key", ""),
                    "name": p.get("name", ""),
                    "id": str(p.get("id", "")),
                }
            )
        return out

    # ---------- Issue ----------
    def get_issue(
        self,
        issue_key: str,
        fields: str = "summary,description,status,assignee,reporter,created,updated,priority,issuetype,project",
    ) -> Dict[str, Any]:
        result = self.get(
            f"issue/{issue_key}",
            params={"fields": fields, "expand": "renderedFields,names"},
        )
        f = result.get("fields", {})
        issue_data = {
            "key": issue_key,
            "title": f.get("summary", ""),
            "status": (f.get("status") or {}).get("name", ""),
            "type": (f.get("issuetype") or {}).get("name", ""),
            "project": (f.get("project") or {}).get("name", ""),
            "priority": (f.get("priority") or {}).get("name", "Not set"),
            "created": f.get("created", "Unknown"),
            "updated": f.get("updated", "Unknown"),
            "reporter": (f.get("reporter") or {}).get("displayName", "Unknown"),
            "assignee": (f.get("assignee") or {}).get("displayName", "Unassigned"),
            "assignee_accountId": (f.get("assignee") or {}).get("accountId", ""),
            "link": self._browse_link(issue_key),
        }
        # rendered description if available
        desc_html = (result.get("renderedFields") or {}).get("description")
        issue_data["description"] = (
            desc_html if desc_html else "<p><em>No description provided</em></p>"
        )
        return issue_data

    def get_comments(self, issue_key: str) -> List[Dict[str, Any]]:
        result = self.get(f"issue/{issue_key}/comment")
        comments = []
        for c in result.get("comments", []) if isinstance(result, dict) else []:
            text = ""
            body = c.get("body") or {}
            for block in body.get("content", []) if isinstance(body, dict) else []:
                for seg in block.get("content", []) if isinstance(block, dict) else []:
                    if "text" in seg:
                        text += seg["text"]
            comments.append(
                {
                    "id": c.get("id", ""),
                    "author": (c.get("author") or {}).get("displayName", "Unknown"),
                    "created": c.get("created", "Unknown"),
                    "updated": c.get("updated", "Unknown"),
                    "text": text,
                }
            )
        return comments

    def _text_to_adf(self, text: str) -> Dict[str, Any]:
        return {
            "type": "doc",
            "version": 1,
            "content": [
                {"type": "paragraph", "content": [{"type": "text", "text": text}]}
            ],
        }

    def add_comment(self, issue_key: str, comment: Any) -> Dict[str, Any]:
        if isinstance(comment, dict):
            body = comment
        else:
            t = (comment or "").strip()
            if not t:
                raise ValueError("comment cannot be empty")
            body = self._text_to_adf(t)

        payload = {"body": body}
        result = self.post(f"issue/{issue_key}/comment", payload)
        return {
            "id": result.get("id"),
            "created": result.get("created"),
            "self": result.get("self"),
            "issue_key": issue_key,
            "issue_link": self._browse_link(issue_key),
        }

    def create_issue(
        self,
        project_key: str,
        summary: str,
        description: str,
        issue_type: str = "Task",
        priority: Optional[str] = None,
    ) -> Dict[str, Any]:
        data = {
            "fields": {
                "project": {"key": project_key},
                "summary": summary,
                "description": self._text_to_adf(description or ""),
                "issuetype": {"name": issue_type or "Task"},
            }
        }
        if priority:
            data["fields"]["priority"] = {"name": priority}

        result = self.post("issue", data)
        key = result.get("key", "")
        return {
            "key": key,
            "id": result.get("id", ""),
            "link": self._browse_link(key) if key else key,
        }

    # ---------- Transitions ----------
    def get_available_transitions(self, issue_key: str) -> List[Dict[str, Any]]:
        r = self.get(f"issue/{issue_key}/transitions")
        out = []
        for t in r.get("transitions", []) if isinstance(r, dict) else []:
            out.append(
                {
                    "id": t.get("id", ""),
                    "name": t.get("name", ""),
                    "to_status": (t.get("to") or {}).get("name", ""),
                }
            )
        return out

    def update_issue_status(
        self,
        issue_key: str,
        transition_id: Optional[str] = None,
        transition_name: Optional[str] = None,
    ) -> Dict[str, Any]:
        if not transition_id and not transition_name:
            raise ValueError("transition_id or transition_name required")

        transitions = self.get_available_transitions(issue_key)
        chosen = None
        if transition_id:
            chosen = next(
                (t["id"] for t in transitions if t["id"] == transition_id), None
            )
        else:
            chosen = next(
                (
                    t["id"]
                    for t in transitions
                    if (t["name"] or "").lower() == (transition_name or "").lower()
                ),
                None,
            )

        if not chosen:
            available = ", ".join([f"{t['name']} (ID: {t['id']})" for t in transitions])
            raise JiraApiError(f"Transition not found. Available: {available}")

        self.post(f"issue/{issue_key}/transitions", {"transition": {"id": chosen}})
        new_status = (
            self.get(f"issue/{issue_key}", params={"fields": "status"})
            .get("fields", {})
            .get("status", {})
            or {}
        ).get("name", "")
        return {
            "issue_key": issue_key,
            "new_status": new_status,
            "link": self._browse_link(issue_key),
        }

    # ---------- Assign (OAuth requires accountId) ----------
    def assign_issue(self, issue_key: str, assignee: str) -> Dict[str, Any]:
        # assignee can be displayName/email fragment; we resolve to accountId
        assignee = (assignee or "").strip()
        if not assignee or assignee.lower() in ("unassigned", "none", "null"):
            payload = {"accountId": None}
        else:
            users = self.search_users(assignee, max_results=10)
            if not users or not users[0].get("accountId"):
                raise JiraApiError(
                    f"User not found for assignee='{assignee}'. Try exact displayName/email fragment."
                )
            payload = {"accountId": users[0]["accountId"]}

        self.put(f"issue/{issue_key}/assignee", payload)
        return {
            "issue_key": issue_key,
            "assignee": assignee or "Unassigned",
            "link": self._browse_link(issue_key),
        }

    # ---------- JQL helpers ----------
    def _autoquote_jql_values(self, jql: str) -> str:
        def _quote_project(m):
            val = m.group(1).strip()
            if val.startswith(("'", '"')):
                return m.group(0)
            if " " in val or "-" in val:
                return f'project = "{val}"'
            return m.group(0)

        jql = re.sub(
            r'(?i)\bproject\s*=\s*([^"\']+?)(?=\s+(AND|OR)\s+|$)', _quote_project, jql
        )

        def _quote_assignee(m):
            val = m.group(1).strip()
            if val.startswith(("'", '"')):
                return m.group(0)
            if " " in val:
                return f'assignee = "{val}"'
            return m.group(0)

        jql = re.sub(
            r'(?i)\bassignee\s*=\s*([^"\']+?)(?=\s+(AND|OR)\s+|$)', _quote_assignee, jql
        )
        return jql

    def _llm_pick_best_project(
        self, project_names: List[str], user_value: str
    ) -> Optional[str]:
        if not self._use_openai or not project_names:
            return None

        prompt = (
            "You are given a user-entered Jira project name and a list of valid Jira project names.\n"
            "Pick the single best matching project name. If none are reasonable, respond exactly: NONE.\n\n"
            f"User value: {user_value}\n"
            f"Choices:\n- " + "\n- ".join(project_names) + "\n\n"
            "Answer with just the chosen name (or NONE)."
        )

        try:
            if hasattr(_OPENAI_CLIENT, "chat") and hasattr(
                _OPENAI_CLIENT.chat, "completions"
            ):
                # new SDK
                resp = _OPENAI_CLIENT.chat.completions.create(  # type: ignore
                    model="gpt-4o-mini",
                    messages=[{"role": "user", "content": prompt}],
                    temperature=0,
                )
                text = (resp.choices[0].message.content or "").strip()
            else:
                # legacy
                resp = _OPENAI_CLIENT.ChatCompletion.create(  # type: ignore
                    model="gpt-4o-mini",
                    messages=[{"role": "user", "content": prompt}],
                    temperature=0,
                )
                text = (resp["choices"][0]["message"]["content"] or "").strip()

            if text and text.upper() != "NONE" and text in project_names:
                return text
        except Exception:
            return None
        return None

    def _resolve_project_name_to_key(self, user_value: str) -> Optional[str]:
        projects = self.search_projects("", max_results=1000)
        if not projects:
            return None

        names = [p["name"] for p in projects if p.get("name")]
        # exact name
        for p in projects:
            if (p.get("name") or "").lower() == user_value.lower():
                return p.get("key")

        # OpenAI best pick
        pick = self._llm_pick_best_project(names, user_value)
        if pick:
            match = next((p for p in projects if p.get("name") == pick), None)
            return match.get("key") if match else None

        # fuzzy name
        close = difflib.get_close_matches(user_value, names, n=1, cutoff=0.6)
        if close:
            chosen = close[0]
            match = next((p for p in projects if p.get("name") == chosen), None)
            if match:
                return match.get("key")

        # fuzzy key
        keys = [p["key"] for p in projects if p.get("key")]
        close_k = difflib.get_close_matches(user_value, keys, n=1, cutoff=0.6)
        if close_k:
            return close_k[0]

        return None

    def _rewrite_project_in_jql(self, jql: str) -> str:
        def _replace(m):
            original = m.group(0)
            val = (m.group(1) or m.group(2) or m.group(3) or "").strip()
            if not val:
                return original
            key = self._resolve_project_name_to_key(val)
            return f"project = {key}" if key else original

        return re.sub(
            r"""(?ix)\bproject\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s)]+))""", _replace, jql
        )

    def _rewrite_assignee_in_jql(self, jql: str) -> str:
        # assignee = <name>  -> assignee = <accountId>
        def _eq_replacer(match):
            original = match.group(0)
            name = next((g for g in match.groups() if g), "").strip()
            if not name:
                return original
            users = self.search_users(name, max_results=5)
            if users and users[0].get("accountId"):
                return f"assignee = {users[0]['accountId']}"
            return original

        jql = re.sub(
            r"""(?ix)\bassignee\s*=\s*(?:'([^']+)'|"([^"]+)"|([^\s)]+))""",
            _eq_replacer,
            jql,
        )

        # assignee in (...)
        def _in_replacer(match):
            original = match.group(0)
            inner = match.group(1)
            names = []
            for raw in inner.split(","):
                s = raw.strip()
                if (s.startswith("'") and s.endswith("'")) or (
                    s.startswith('"') and s.endswith('"')
                ):
                    s = s[1:-1]
                if s:
                    names.append(s)

            ids = []
            for n in names:
                users = self.search_users(n, max_results=5)
                if users and users[0].get("accountId"):
                    ids.append(users[0]["accountId"])

            if ids:
                return f"assignee in ({','.join(ids)})"
            return original

        jql = re.sub(r"(?i)\bassignee\s+in\s*\(([^)]+)\)", _in_replacer, jql)
        return jql

    # ---------- Search (must use /search/jql) ----------
    def search(self, query: str, max_results: int = 10) -> Dict[str, Any]:
        query = (query or "").strip()
        if not query:
            raise ValueError("query is required")

        # If it's already JQL-like, keep it. Otherwise build text search.
        if any(
            op in query for op in ["=", "~", ">", "<", " AND ", " OR ", " ORDER BY "]
        ):
            jql = query
        else:
            terms = query.split()
            jql = (
                " OR ".join([f'text ~ "{t}"' for t in terms])
                if terms
                else f'text ~ "{query}"'
            )

        jql = self._autoquote_jql_values(jql)
        jql = self._rewrite_project_in_jql(jql)
        jql = self._rewrite_assignee_in_jql(jql)

        body = {
            "jql": jql,
            "maxResults": max_results,
            "fields": [
                "summary",
                "status",
                "issuetype",
                "priority",
                "updated",
                "assignee",
                "project",
            ],
        }

        # REQUIRED endpoint on your Jira instance
        data = self.post("search/jql", body)

        if "issues" not in data:
            raise JiraApiError(f"Unexpected Jira response keys: {list(data.keys())}")

        issues = []
        for item in data.get("issues", []):
            f = item.get("fields", {}) or {}
            assignee = f.get("assignee") or {}
            project = f.get("project") or {}
            key = item.get("key", "Unknown")
            issues.append(
                {
                    "key": key,
                    "summary": f.get("summary", ""),
                    "status": (f.get("status") or {}).get("name", ""),
                    "type": (f.get("issuetype") or {}).get("name", ""),
                    "priority": (f.get("priority") or {}).get("name", "Not set"),
                    "updated": f.get("updated", "Unknown"),
                    "assignee": assignee.get("displayName", "Unassigned"),
                    "assignee_accountId": assignee.get("accountId", ""),
                    "project_key": project.get("key", ""),
                    "project_name": project.get("name", ""),
                    "link": self._browse_link(key),
                }
            )

        return {
            "issues": issues,
            "total": data.get("total", len(issues)),
            "displayed": len(issues),
            "jql": jql,
        }


