# Tools (OpenWebUI)
# -----------------------------
class Tools:
    def __init__(self):
        self.valves = self.Valves()

    class Valves(BaseModel):
        # Atlassian OAuth (3LO) - load from env for security
        ATLASSIAN_CLIENT_ID: str = Field(
            default_factory=lambda: os.getenv("ATLASSIAN_CLIENT_ID", "")
        )
        ATLASSIAN_CLIENT_SECRET: str = Field(
            default_factory=lambda: os.getenv("ATLASSIAN_CLIENT_SECRET", "")
        )
        ATLASSIAN_REDIRECT_URI: str = Field(
            default_factory=lambda: os.getenv("ATLASSIAN_REDIRECT_URI", "")
        )
        ATLASSIAN_SCOPES: str = Field(
            default_factory=lambda: os.getenv(
                "ATLASSIAN_SCOPES", "read:jira-work write:jira-work offline_access"
            )
        )
        ATLASSIAN_AUDIENCE: str = Field(
            default_factory=lambda: os.getenv("ATLASSIAN_AUDIENCE", "api.atlassian.com")
        )

        # Optional OpenAI for project-name matching (no base URL)
        OPENAI_API_KEY: str = Field(
            default_factory=lambda: os.getenv("OPENAI_API_KEY", "")
        )

        @field_validator("ATLASSIAN_REDIRECT_URI")
        @classmethod
        def _validate_redirect(cls, v: str) -> str:
            if v and not v.startswith(("http://", "https://")):
                raise ValueError(
                    "ATLASSIAN_REDIRECT_URI must start with http:// or https://"
                )
            return v

        @model_validator(mode="after")
        def _validate_oauth(self):
            # Allow tool to load even if env not set, but connect will fail with clear error.
            return self

    # ---------- User identity ----------
    def _user_key(self, __user__: dict) -> str:
        return str(__user__.get("id") or __user__.get("email") or "")

    # ---------- Token store ops (replace with encrypted DB in production) ----------
    def _token_path(self, user_key: str) -> str:
        safe_key = user_key.replace("/", "_").replace(":", "_")
        return os.path.join(BASE_TOKEN_DIR, f"user_{safe_key}.json")

    def _get_user_record(self, user_key: str) -> Dict[str, Any]:
        path = self._token_path(user_key)
        if not os.path.exists(path):
            return {}

        with _TOKEN_LOCK:
            try:
                with open(path, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception:
                return {}

    def _set_user_record(self, user_key: str, rec: Dict[str, Any]) -> None:
        path = self._token_path(user_key)
        with _TOKEN_LOCK:
            with open(path, "w", encoding="utf-8") as f:
                json.dump(rec, f, indent=2)

    def _delete_user_record(self, user_key: str) -> None:
        with _TOKEN_LOCK:
            if user_key in TOKEN_STORE:
                del TOKEN_STORE[user_key]

    # ---------- OAuth helper ----------
    def _oauth(self) -> AtlassianOAuth:
        return AtlassianOAuth(
            client_id=self.valves.ATLASSIAN_CLIENT_ID,
            client_secret=self.valves.ATLASSIAN_CLIENT_SECRET,
            redirect_uri=self.valves.ATLASSIAN_REDIRECT_URI,
            scopes=self.valves.ATLASSIAN_SCOPES,
            audience=self.valves.ATLASSIAN_AUDIENCE,
        )

    def _is_expired(self, rec: Dict[str, Any]) -> bool:
        exp = int(rec.get("expires_at") or 0)
        # refresh 60s early
        return exp > 0 and (time.time() >= (exp - 60))

    def _refresh_if_needed(self, user_key: str) -> Dict[str, Any]:
        rec = self._get_user_record(user_key)
        if not rec:
            return rec
        if not self._is_expired(rec):
            return rec
        refresh_token = rec.get("refresh_token") or ""
        if not refresh_token:
            return rec

        oauth = self._oauth()
        newtok = oauth.refresh_access_token(refresh_token)
        access_token = newtok.get("access_token") or ""
        new_refresh = newtok.get("refresh_token") or refresh_token
        expires_in = int(newtok.get("expires_in") or 3600)
        rec["access_token"] = access_token
        rec["refresh_token"] = new_refresh
        rec["expires_at"] = int(time.time() + expires_in)
        self._set_user_record(user_key, rec)
        return rec

    # ---------- Jira client ----------
    def _get_jira_client(self, __user__: dict) -> Jira:
        user_key = self._user_key(__user__)
        if not user_key:
            raise JiraApiError("User identity not available from OpenWebUI (__user__).")

        rec = self._refresh_if_needed(user_key)
        if not rec:
            raise JiraApiError("Jira account not connected. Run jira_connect first.")

        access_token = rec.get("access_token") or ""
        cloud_id = rec.get("cloud_id") or ""
        cloud_url = rec.get("cloud_url") or ""
        if not access_token or not cloud_id:
            raise JiraApiError(
                "Jira token/cloudId missing. Run jira_connect + jira_complete_auth again."
            )

        return Jira(
            access_token=access_token,
            cloud_id=cloud_id,
            cloud_url=cloud_url,
            openai_api_key=self.valves.OPENAI_API_KEY,
        )

    # ==========================================================
    # OAuth / Connection Tools
    # ==========================================================
    async def jira_connect(
        self,
        __event_emitter__: Callable[[dict], Awaitable[None]],
        __user__: dict = {},
    ):
        """
        Step 1: Generate Atlassian OAuth authorization URL for the current user.
        User opens it, authorizes, then Atlassian redirects to your REDIRECT_URI with ?code=...&state=...
        """
        ee = EventEmitter(__event_emitter__)
        try:
            await ee.emit_status("Preparing Jira OAuth authorization link...", False)

            user_key = self._user_key(__user__)
            if not user_key:
                raise JiraApiError("User identity not available (__user__).")

            oauth = self._oauth()

            # include user_key in state so we can bind callback securely
            state = f"{user_key}:{uuid.uuid4().hex}"
            url = oauth.build_authorize_url(state)

            msg = (
                "### 🔐 Connect Jira (OAuth)\n\n"
                "1) Open this link and authorize:\n\n"
                f"{url}\n\n"
                "2) After approval, you will be redirected to your redirect URL with **code** and **state**.\n"
                "3) Copy the **code** and **state** and call `jira_complete_auth`.\n"
            )
            await ee.emit_message(msg)
            await ee.emit_status("OAuth link generated.", True)
            return json.dumps({"auth_url": url, "state_hint": state})
        except Exception as e:
            await ee.emit_status(f"Failed to generate OAuth link: {str(e)}", True, True)
            return f"Error: {str(e)}"

    async def jira_complete_auth(
        self,
        code: str,
        state: str,
        __event_emitter__: Callable[[dict], Awaitable[None]],
        __user__: dict = {},
    ):
        """
        Step 2: Exchange code for tokens and store them for this user.
        Also fetch cloudId via accessible-resources.
        """
        ee = EventEmitter(__event_emitter__)
        try:
            await ee.emit_status("Completing Jira OAuth connection...", False)

            code = (code or "").strip()
            state = (state or "").strip()
            if not code or not state:
                raise ValueError("code and state are required")

            user_key = self._user_key(__user__)
            if not user_key:
                raise JiraApiError("User identity not available (__user__).")

            # Bind state to the current user
            if not state.startswith(f"{user_key}:"):
                raise JiraApiError(
                    "State does not match current user. Please run jira_connect again from this account."
                )

            oauth = self._oauth()
            tok = oauth.exchange_code_for_token(code)

            access_token = tok.get("access_token") or ""
            refresh_token = tok.get("refresh_token") or ""
            expires_in = int(tok.get("expires_in") or 3600)
            if not access_token:
                raise JiraApiError(
                    f"OAuth token exchange returned no access_token: {tok}"
                )

            # Find cloudId(s) user can access
            resources = oauth.get_accessible_resources(access_token)
            if not resources:
                raise JiraApiError("No accessible Jira resources found for this user.")

            # Prefer the first Jira resource. (You can customize selection later.)
            chosen = resources[0]
            cloud_id = chosen.get("id") or ""
            cloud_url = chosen.get("url") or ""  # https://xxx.atlassian.net

            if not cloud_id:
                raise JiraApiError(
                    f"accessible-resources did not include an id: {chosen}"
                )

            rec = {
                "access_token": access_token,
                "refresh_token": refresh_token,
                "expires_at": int(time.time() + expires_in),
                "cloud_id": cloud_id,
                "cloud_url": cloud_url,
                "resource_name": chosen.get("name") or "",
            }
            self._set_user_record(user_key, rec)

            await ee.emit_message(
                "### ✅ Jira connected\n\n"
                f"- Site: **{rec.get('resource_name','')}**\n"
                f"- URL: {cloud_url}\n"
                f"- cloudId: `{cloud_id}`\n\n"
                "You can now use search/view/create/comment as this user."
            )
            await ee.emit_status("Jira OAuth connection saved.", True)
            return json.dumps(
                {"connected": True, "cloud_id": cloud_id, "cloud_url": cloud_url}
            )
        except Exception as e:
            await ee.emit_status(f"Failed to complete OAuth: {str(e)}", True, True)
            return f"Error: {str(e)}"

    async def jira_disconnect(
        self,
        __event_emitter__: Callable[[dict], Awaitable[None]],
        __user__: dict = {},
    ):
        ee = EventEmitter(__event_emitter__)
        try:
            user_key = self._user_key(__user__)
            if not user_key:
                raise JiraApiError("User identity not available (__user__).")
            self._delete_user_record(user_key)
            await ee.emit_message("### ✅ Jira disconnected for this user.")
            return json.dumps({"disconnected": True})
        except Exception as e:
            await ee.emit_status(f"Failed to disconnect: {str(e)}", True, True)
            return f"Error: {str(e)}"

    async def jira_connection_status(
        self,
        __event_emitter__: Callable[[dict], Awaitable[None]],
        __user__: dict = {},
    ):
        ee = EventEmitter(__event_emitter__)
        try:
            user_key = self._user_key(__user__)
            rec = self._get_user_record(user_key)
            if not rec:
                await ee.emit_message(
                    "### ❌ Not connected to Jira\n\nRun `jira_connect`."
                )
                return json.dumps({"connected": False})
            expired = self._is_expired(rec)
            await ee.emit_message(
                "### ✅ Connected to Jira\n\n"
                f"- Site: **{rec.get('resource_name','')}**\n"
                f"- URL: {rec.get('cloud_url','')}\n"
                f"- Token expires soon: **{expired}**\n"
            )
            return json.dumps(
                {
                    "connected": True,
                    "cloud_url": rec.get("cloud_url", ""),
                    "expires_soon": expired,
                }
            )
        except Exception as e:
            await ee.emit_status(f"Failed to check status: {str(e)}", True, True)
            return f"Error: {str(e)}"

