    async def search_issues(
        self,
        query: str,
        __event_emitter__: Callable[[dict], Awaitable[None]],
        max_results: int = 10,
        __user__: dict = {},
    ):
        ee = EventEmitter(__event_emitter__)
        try:
            await ee.emit_status(f"Searching Jira for: {query}", False)
            jira = self._get_jira_client(__user__)
            results = jira.search(query, max_results=max_results)

            if not results.get("issues"):
                await ee.emit_status("No issues found.", True)
                return json.dumps(
                    {
                        "message": "No issues found",
                        "total": 0,
                        "jql": results.get("jql"),
                    }
                )

            headers = [
                "Key",
                "Summary",
                "Status",
                "Type",
                "Priority",
                "Updated",
                "Assignee",
                "Project",
            ]
            rows = []
            for it in results["issues"]:
                key = it.get("key", "")
                link = it.get("link", key)
                rows.append(
                    [
                        f"[{key}]({link})" if link.startswith("http") else key,
                        it.get("summary", ""),
                        it.get("status", ""),
                        it.get("type", ""),
                        it.get("priority", ""),
                        it.get("updated", ""),
                        it.get("assignee", "Unassigned"),
                        it.get("project_name", "") or it.get("project_key", ""),
                    ]
                )

            await ee.emit_table(
                headers,
                rows,
                title=f"Found {results.get('total', 0)} issues (showing {results.get('displayed', 0)})",
            )
            await ee.emit_status("Search complete.", True)
            return json.dumps(results)

        except Exception as e:
            await ee.emit_status(f"Failed to search issues: {str(e)}", True, True)
            return f"Error: {str(e)}"

    async def get_issue(
        self,
        issue_id: str,
        __event_emitter__: Callable[[dict], Awaitable[None]],
        __user__: dict = {},
    ):
        ee = EventEmitter(__event_emitter__)
        try:
            await ee.emit_status(f"Retrieving Jira issue {issue_id}", False)
            jira = self._get_jira_client(__user__)
            issue = jira.get_issue(issue_id)

            link = issue.get("link", issue_id)
            card = (
                f"### 📩 {issue['key']}: {issue['title']}\n\n"
                f"**Status:** {issue['status']}\n\n"
                f"**Type:** {issue['type']}\n\n"
                f"**Priority:** {issue['priority']}\n\n"
                f"**Project:** {issue['project']}\n\n"
                f"**Created:** {issue['created']}\n\n"
                f"**Updated:** {issue['updated']}\n\n"
                f"**Reporter:** {issue['reporter']}\n\n"
                f"**Assignee:** {issue['assignee']}\n\n"
                + (
                    f"**Link:** [{issue['key']}]({link})\n"
                    if isinstance(link, str) and link.startswith("http")
                    else ""
                )
            )
            await ee.emit_message(card)

            # comments
            comments = jira.get_comments(issue_id)
            if comments:
                msg = f"### 💬 Comments on {issue_id} ({len(comments)})\n\n"
                for i, c in enumerate(comments):
                    msg += f"**{i+1}. {c['author']}** — {c['created']}\n{c['text']}\n\n"
                await ee.emit_message(msg)

            await ee.emit_status("Issue retrieved.", True)
            return json.dumps(issue)
        except Exception as e:
            await ee.emit_status(f"Failed to get issue: {str(e)}", True, True)
            return f"Error: {str(e)}"

